// Max distance travelled in a single sub-step, small enough that the ball cannot
// tunnel through a brick between two checks.
const MAX_SUBSTEP = 4;

export function step(state, dt) {
  const { ball, paddle } = state;
  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const n = Math.max(1, Math.ceil(distance / MAX_SUBSTEP));
  const subDt = dt / n;

  let lost = false;
  for (let i = 0; i < n; i++) {
    // move
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // walls
    if (ball.x - ball.r < 0) { ball.x = ball.r; ball.vx = Math.abs(ball.vx); }
    else if (ball.x + ball.r > WIDTH) { ball.x = WIDTH - ball.r; ball.vx = -Math.abs(ball.vx); }
    if (ball.y - ball.r < 0) { ball.y = ball.r; ball.vy = Math.abs(ball.vy); }
    if (ball.y - ball.r > HEIGHT) { lost = true; }

    // bricks
    resolveBricks(state);

    // paddle
    if (...) ...
  }

  if (lost) return true;
  return false;
}
```

