// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Max distance (px) travelled per physics sub-step. Small enough that the ball
// cannot travel clear across a brick between two collision checks, which would
// let it tunnel through (see ISSUES.md #1 / #4 "tunnelling").
const MAX_SUBSTEP = 6;

// Pushes the ball out of a brick along X, to whichever side was hit.
function pushOutX(ball, brick, fromLeft, fromRight) {
  if (fromLeft <= fromRight) ball.x = brick.x - ball.r;
  else ball.x = brick.x + brick.w + ball.r;
}

// Pushes the ball out of a brick along Y, to whichever side was hit.
function pushOutY(ball, brick, fromAbove, fromBelow) {
  if (fromAbove <= fromBelow) ball.y = brick.y - ball.r;
  else ball.y = brick.y + brick.h + ball.r;
}

// Resolves collisions of the ball with every live brick: destroys the brick
// it hits, awards score/combo, and bounces the ball back out.
//
// Per-face bounce: the axis with the smaller penetration is the face that was
// hit — flip `vy` on a top/bottom hit, `vx` on a side hit, and (for an equal
// penetration = diagonal) flip both. Push-out repositions the ball just outside
// the brick so it does not stick and re-flip forever. Each axis is flipped at
// most once per pass so a ball resting on the seam between two adjacent bricks
// (gap 8px < ball diameter 14px, so it overlaps both in the same pass) does not
// cancel its own bounce.
function resolveBricks(state) {
  const { ball } = state;
  let flippedX = false;
  let flippedY = false;

  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Penetration depth past each inner face of the brick (all positive when overlapping).
    const fromLeft = ball.x + ball.r - brick.x;
    const fromRight = brick.x + brick.w - (ball.x - ball.r);
    const fromAbove = ball.y + ball.r - brick.y;
    const fromBelow = brick.y + brick.h - (ball.y - ball.r);
    const penX = Math.min(fromLeft, fromRight);
    const penY = Math.min(fromAbove, fromBelow);

    if (penX < penY) {
      // Side hit: bounce horizontally, push out along X.
      if (!flippedX) ball.vx = -ball.vx;
      flippedX = true;
      pushOutX(ball, brick, fromLeft, fromRight);
    } else if (penY < penX) {
      // Top/bottom hit: bounce vertically, push out along Y.
      if (!flippedY) ball.vy = -ball.vy;
      flippedY = true;
      pushOutY(ball, brick, fromAbove, fromBelow);
    } else {
      // Corner (equal penetration): bounce both axes.
      if (!flippedX) ball.vx = -ball.vx;
      if (!flippedY) ball.vy = -ball.vy;
      flippedX = true;
      flippedY = true;
      pushOutX(ball, brick, fromLeft, fromRight);
      pushOutY(ball, brick, fromAbove, fromBelow);
    }
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks (see #1). The movement is sub-stepped so
// a fast ball cannot tunnel straight through a brick between two frames (see
// ISSUES.md #1 / "tunnelling").
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const travelled = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(travelled / MAX_SUBSTEP));
  const subDt = dt / substeps;

  for (let s = 0; s < substeps; s++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Bricks
    resolveBricks(state);

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

